1	import { expect, test, type Page } from "@playwright/test";
2	import { acquirePointerLock } from "./helpers";
3	
4	/**
5	 * The full co-op journey against the real online stack: the Next app backed
6	 * by an in-process Postgres (DATABASE_URL=pglite://memory) plus the Bun game
7	 * server, both from playwright.config's webServer list — no Docker, no cloud.
8	 * Two isolated browser contexts play two ACCOUNTS (online play is
9	 * accounts-only): the host registers, creates an online profile and world
10	 * through the account menus, the friend registers on the invite landing page,
11	 * and the pair must see each other, share block edits, and chat.
12	 */
13	
14	/** Console/page errors collected like the smoke fixture does (favicon 404 is noise). */
15	function watchErrors(page: Page, sink: string[]): void {
16	  page.on("console", (message) => {
17	    if (message.type() !== "error") return;
18	    if (message.text().includes("Failed to load resource") && message.location().url.endsWith("/favicon.ico")) return;
19	    sink.push(`${message.text()} (${message.location().url})`);
20	  });
21	  page.on("pageerror", (error) => sink.push(String(error)));
22	}
23	
24	/** Booted, synced, and drawing: the bar every online entry must clear. */
25	async function waitForOnlineGame(page: Page): Promise<void> {
26	  await page.waitForFunction(() => window.__monecraft !== undefined, undefined, { timeout: 30000 });
27	  await page.waitForFunction(() => window.__monecraft!.net?.status() === "online", undefined, { timeout: 30000 });
28	  await page.waitForFunction(() => window.__monecraft!.renderer.renderedTriangles() > 0, undefined, { timeout: 30000 });
29	}
30	
31	/** Registers a fresh account: welcome gate's "Sign in" → auth screen → sign-up. */
32	async function signUp(page: Page, name: string, email: string): Promise<void> {
33	  await page.getByRole("button", { name: "Sign in", exact: true }).click();
34	  await page.getByRole("button", { name: "I need an account" }).click();
35	  await page.getByLabel("Email").fill(email);
36	  await page.getByLabel("Display name").fill(name);
37	  await page.getByLabel("Password").fill("hunter2hunter2");
38	  await page.getByRole("button", { name: "Create account" }).click();
39	}
40	
41	/** From the account home, creates an online profile and enters its world list. */
42	async function createOnlineProfile(page: Page, name: string): Promise<void> {
43	  // Sign-up → session probe → account home spans two network hops.
44	  await expect(page.getByText("Online Profiles")).toBeVisible({ timeout: 15000 });
45	  await page.getByTestId("new-online-profile").click();
46	  await page.getByLabel("Profile name").fill(name);
47	  // exact: "Create account" (form) and "Create World" share the substring.
48	  await page.getByRole("button", { name: "Create", exact: true }).click();
49	}
50	
51	test("two accounts share an online world via an invite link", async ({ browser }) => {
52	  // Two production builds of the game plus a WebSocket handshake each; CI
53	  // renders with software GL, so the whole journey gets a generous ceiling.
54	  test.setTimeout(240000);
55	  const errors: string[] = [];
56	  // The pglite webServer keeps its data across retries within one run, so a
57	  // fixed email means every retry dies on "User already exists" — tag them.
58	  const runTag = Date.now().toString(36);
59	
60	  // ── the host: register → online profile → online world → in-game ─────────
61	  const hostContext = await browser.newContext();
62	  const host = await hostContext.newPage();
63	  watchErrors(host, errors);
64	  await host.goto("/");
65	
66	  // The welcome gate's "Sign in" leads straight to the auth screen, so
67	  // registration needs no local profile — a pure account never touches the
68	  // local menus.
69	  await signUp(host, "Hosta", `host-${runTag}@example.com`);
70	  await createOnlineProfile(host, "Hosta");
71	
72	  // Creative, so the host's block breaks are instant on the server side.
73	  await host.getByTestId("new-online-world").click();
74	  await host.getByLabel("World name").fill("Co-op Test");
75	  await host.getByLabel("World seed").fill("4242");
76	  await host.getByRole("button", { name: "Creative mode" }).click();
77	  await host.getByRole("button", { name: "Create World" }).click();
78	  await waitForOnlineGame(host);
79	
80	  // Mint the invite with the host's cookies (the menu's Copy button wraps the
81	  // same endpoint; the clipboard is out of reach in headless runs).
82	  const worldId = await host.evaluate(async () => {
83	    const response = await fetch("/api/worlds");
84	    const { worlds } = (await response.json()) as { worlds: Array<{ id: string }> };
85	    return worlds[0].id;
86	  });
87	  const inviteToken = await host.evaluate(async (id) => {
88	    const response = await fetch(`/api/worlds/${id}/invites`, { method: "POST" });
89	    const { token } = (await response.json()) as { token: string };
90	    return token;
91	  }, worldId);
92	
93	  // ── the friend: invite link → register on the landing page → same world ──
94	  const friendContext = await browser.newContext();
95	  const friend = await friendContext.newPage();
96	  watchErrors(friend, errors);
97	  await friend.goto(`/join/${inviteToken}`);
98	
99	  // The landing page previews the world before any sign-in, then embeds the
100	  // account panel; registering accepts the invite in place.
101	  await expect(friend.getByText("Co-op Test")).toBeVisible({ timeout: 15000 });
102	  await expect(friend.getByText(/sign in to join/)).toBeVisible();
103	  await signUp(friend, "Frienda", `friend-${runTag}@example.com`);
104	  await expect(friend.getByText(/You've joined/)).toBeVisible({ timeout: 15000 });
105	  await friend.getByRole("link", { name: "Open the game" }).click();
106	
107	  // The landing page marked online-used, so the shell finds the fresh session
108	  // and opens the account home. The joined world surfaces under any profile
109	  // (membership is account-level), labelled as joined rather than owned.
110	  await createOnlineProfile(friend, "Friend");
111	  await expect(friend.getByTestId(`online-world-${worldId}`)).toContainText("Joined");
112	  await friend.getByTestId(`online-world-${worldId}`).click();
113	  await waitForOnlineGame(friend);
114	
115	  // ── both replicas agree there are two players in the room ────────────────
116	  for (const page of [host, friend]) {
117	    await page.waitForFunction(() => window.__monecraft!.engine.state.players.size === 2, undefined, { timeout: 15000 });
118	  }
119	
120	  // ── a block edit crosses the wire ─────────────────────────────────────────
121	  // The host digs straight down. The host's own journal entry may be its
122	  // PREDICTED break (replica mining commits locally now), so the proof that
123	  // the server decided and broadcast it is the FRIEND's journal changing.
124	  await acquirePointerLock(host);
125	  await host.waitForTimeout(1000); // settle (slow CI renderers need the margin)
126	  await host.evaluate(() => {
127	    window.__monecraft!.engine.state.player.pitch = -Math.PI / 2 + 0.02;
128	  });
