1	import type { GameEngine } from "@/lib/game/engine/GameEngine";
2	import type { FrameInput, MoveIntents } from "@/lib/game/engine/state";
3	import {
4	  FLY_DOUBLE_TAP_WINDOW_SECONDS,
5	  TOUCH_HOLD_MINE_MS,
6	  TOUCH_JOYSTICK_DEADZONE,
7	  TOUCH_JOYSTICK_RADIUS_PX,
8	  TOUCH_LOOK_SENSITIVITY,
9	  TOUCH_SPRINT_DOUBLE_TAP_MS,
10	  TOUCH_TAP_MAX_MS,
11	  TOUCH_TAP_SLOP_PX
12	} from "@/lib/game/config";
13	import type { InputController } from "./inputController";
14	import { isUiBlocked } from "./inputGating";
15	
16	/**
17	 * The touch counterpart of createInputController: same InputController
18	 * surface, but "gameplay capture" is a virtual `active` flag (there is no
19	 * pointer lock on touch — tap-to-play calls engage()). All gesture state
20	 * lives here, DOM-free: the TouchControls overlay forwards plain pointer
21	 * records into `controls`, so this whole state machine unit-tests without a
22	 * browser. The engine contract is identical to desktop: mutate FrameInput,
23	 * call engine.applyLook, dispatch Commands.
24	 *
25	 * Gesture model (Minecraft-PE classic): on the free look area, drag = look,
26	 * tap = one attack, press-and-hold within slop = attack + mineHeld until
27	 * lift — and a drag that leaves the slop first is ONLY ever a look (a camera
28	 * swipe must never dig). Movement rides a fixed-base joystick with 8-way
29	 * sectors; re-engaging the stick quickly latches sprint (applied only while
30	 * pushing forward); Jump double-tap toggles flight, mirroring Space.
31	 */
32	
33	export type TouchPointer = { pointerId: number; x: number; y: number };
34	export type TouchActionButton = "jump" | "sneak" | "place" | "eat";
35	
36	export type TouchControlsApi = {
37	  /** Joystick coords are relative to the stick's center (the overlay converts). */
38	  joystickDown(p: TouchPointer): void;
39	  joystickMove(p: TouchPointer): void;
40	  joystickUp(pointerId: number): void;
41	  /** Look coords are viewport CSS px (only deltas matter). */
42	  lookDown(p: TouchPointer): void;
43	  lookMove(p: TouchPointer): void;
44	  lookUp(pointerId: number): void;
45	  /** pointercancel: lift with no tap classification. */
46	  lookCancel(pointerId: number): void;
47	  buttonDown(button: TouchActionButton): void;
48	  buttonUp(button: TouchActionButton): void;
49	  readonly sneakLatched: boolean;
50	};
51	
52	export type TouchInputController = InputController & { controls: TouchControlsApi };
53	
54	type CreateTouchInputControllerArgs = {
55	  engine: GameEngine;
56	  onLockChange: (locked: boolean) => void;
57	  /** Injectable time/scheduling so tap-vs-hold tests are deterministic. */
58	  now?: () => number;
59	  schedule?: (fn: () => void, ms: number) => number;
60	  cancel?: (id: number) => void;
61	};
62	
63	/** 8-way sector threshold on the normalized joystick vector (sin of 22.5°). */
64	const DIAG = Math.sin(Math.PI / 8);
65	
66	export function createTouchInputController(args: CreateTouchInputControllerArgs): TouchInputController {
67	  const { engine, onLockChange } = args;
68	  const now = args.now ?? (() => performance.now());
69	  const schedule = args.schedule ?? ((fn, ms) => window.setTimeout(fn, ms));
70	  const cancel = args.cancel ?? ((id) => window.clearTimeout(id));
71	
72	  const move: MoveIntents = { forward: false, back: false, left: false, right: false, jump: false, sprint: false, crouch: false };
73	  const input: FrameInput = { move, mineHeld: false };
74	
75	  let active = false;
76	  let sneakLatch = false;
77	
78	  type LookGesture = {
79	    pointerId: number;
80	    startX: number;
81	    startY: number;
82	    lastX: number;
83	    lastY: number;
84	    startedAt: number;
85	    drift: number;
86	    mining: boolean;
87	    holdTimer: number | null;
88	  };
89	  let look: LookGesture | null = null;
90	
91	  type JoystickGesture = { pointerId: number; sprintLatch: boolean };
92	  let joystick: JoystickGesture | null = null;
93	  let lastJoystickEngageAt = -Infinity;
94	  let lastJumpTapAt = -Infinity;
95	
96	  const gated = () => !active || isUiBlocked(engine);
97	
98	  const clearJoystick = () => {
99	    joystick = null;
100	    move.forward = move.back = move.left = move.right = false;
101	    move.sprint = false;
102	  };
103	
104	  const clearLook = () => {
105	    if (look?.holdTimer != null) cancel(look.holdTimer);
106	    look = null;
107	    input.mineHeld = false;
108	  };
109	
110	  const applyJoystickVector = (x: number, y: number) => {
111	    const len = Math.hypot(x, y);
112	    if (len < TOUCH_JOYSTICK_DEADZONE * TOUCH_JOYSTICK_RADIUS_PX) {
113	      move.forward = move.back = move.left = move.right = false;
114	    } else {
115	      const nx = x / len;
116	      const ny = y / len;
117	      move.left = nx < -DIAG;
118	      move.right = nx > DIAG;
119	      move.forward = ny < -DIAG; // screen y grows downward
120	      move.back = ny > DIAG;
121	    }
122	    // Sprint needs both the quick re-engage latch and an actual forward push.
123	    move.sprint = (joystick?.sprintLatch ?? false) && move.forward;
124	  };
125	
126	  const controls: TouchControlsApi = {
127	    joystickDown(p) {
128	      if (gated() || joystick) return;
129	      const engagedAt = now();
130	      joystick = { pointerId: p.pointerId, sprintLatch: engagedAt - lastJoystickEngageAt <= TOUCH_SPRINT_DOUBLE_TAP_MS };
131	      lastJoystickEngageAt = engagedAt;
132	      applyJoystickVector(p.x, p.y);
133	    },
134	
135	    joystickMove(p) {
136	      if (!joystick || joystick.pointerId !== p.pointerId) return;
137	      if (gated()) return clearJoystick();
138	      applyJoystickVector(p.x, p.y);
139	    },
140	
141	    joystickUp(pointerId) {
142	      if (joystick?.pointerId !== pointerId) return;
143	      clearJoystick();
144	    },
145	
146	    lookDown(p) {
147	      if (gated() || look) return; // first look finger wins; extras ignored
148	      const holdTimer = schedule(() => {
149	        // Held still long enough: this is a mine, not a tap or a drag.
150	        if (!look || look.drift > TOUCH_TAP_SLOP_PX || gated()) return;
151	        look.mining = true;
152	        look.holdTimer = null;
153	        input.mineHeld = true;
154	        engine.dispatch({ type: "attack" }); // desktop mousedown parity: the swing starts the dig
155	      }, TOUCH_HOLD_MINE_MS);
156	      look = { pointerId: p.pointerId, startX: p.x, startY: p.y, lastX: p.x, lastY: p.y, startedAt: now(), drift: 0, mining: false, holdTimer };
