          <button
            type="button"
            className="touch-btn"
            data-testid="touch-eat"
            onPointerDown={() => controls.buttonDown("eat")}
            onPointerUp={() => controls.buttonUp("eat")}
            onPointerCancel={() => controls.buttonUp("eat")}
          >
            Eat
          </button>
        ) : null}
