// A high-frequency IN-PAGE watcher latches the ledger's PENDING window,
// decoupled from the Playwright poll. The pending entry lives only for one
// simulated round trip (~700–1800 ms), and cross-process `evaluate` round
// trips under load can space the poll's samples wider than that and skip
// over it (the observed `pendingSeen: false` while `broke: true`). With the
// friend foregrounded (above), a 16 ms timer runs un-throttled and samples
// the ledger far faster than the poll, so it cannot miss the window. (An
// in-page watcher was rejected on 2026-07-05 only because the friend page
// was occluded and its timers/rAF were throttled — bringToFront fixes that.)
await friend.evaluate(() => {
  const w = window as unknown as { __sawPending?: boolean; __pendingWatch?: number };
  w.__sawPending = false;
  w.__pendingWatch = window.setInterval(() => {
    if ((window.__monecraft?.net?.netStats().pendingPredictions ?? 0) > 0) w.__sawPending = true;
  }, 16);
});
await friend.mouse.down();
// Poll until the break commits locally (`broke` is a persistent state once
// it flips) and the watcher has latched a pending entry.
const samples: string[] = [];
let last: { broke: boolean; pendingSeen: boolean } = { broke: false, pendingSeen: false };
for (let i = 0; i < 300; i += 1) {
  last = await friend.evaluate((before) => {
    const w = window as unknown as { __sawPending?: boolean };
    const st = window.__monecraft!.engine.state as unknown as {
      player: { mining?: { targetKey: string; progress: number } };
    };
    return {
      broke: window.__monecraft!.engine.state.blockChanges.changes().length > before,
      pendingSeen: w.__sawPending === true,
      pending: window.__monecraft!.net!.netStats().pendingPredictions,
      edits: window.__monecraft!.engine.state.blockChanges.changes().length,
      mine: `${st.player.mining?.targetKey ?? "?"}@${(st.player.mining?.progress ?? 0).toFixed(2)}`
    };
  }, friendEdits);
  samples.push(`${i * 100}ms ${JSON.stringify(last)}`);
  if (last.broke && last.pendingSeen) break;
  await friend.waitForTimeout(100);
}
await friend.evaluate(() => {
  const w = window as unknown as { __pendingWatch?: number };
  if (w.__pendingWatch) window.clearInterval(w.__pendingWatch);
});
if (!(last.broke && last.pendingSeen)) console.log("LAGGED-BREAK SAMPLES:\n" + samples.join("\n"));
expect(last, "the lagged break commits locally through the prediction ledger").toMatchObject({ broke: true, pendingSeen: true });

