1	import { expect, test, type Page } from "@playwright/test";
2	
3	/**
4	 * The full co-op journey against the real online stack: the Next app backed
5	 * by an in-process Postgres (DATABASE_URL=pglite://memory) plus the Bun game
6	 * server, both from playwright.config's webServer list — no Docker, no cloud.
7	 * Two isolated browser contexts play two ACCOUNTS (online play is
8	 * accounts-only): the host registers, creates an online profile and world
9	 * through the account menus, the friend registers on the invite landing page,
10	 * and the pair must see each other, share block edits, and chat.
11	 */
12	
13	/** Console/page errors collected like the smoke fixture does (favicon 404 is noise). */
14	function watchErrors(page: Page, sink: string[]): void {
15	  page.on("console", (message) => {
16	    if (message.type() !== "error") return;
17	    if (message.text().includes("Failed to load resource") && message.location().url.endsWith("/favicon.ico")) return;
18	    sink.push(`${message.text()} (${message.location().url})`);
19	  });
20	  page.on("pageerror", (error) => sink.push(String(error)));
21	}
22	
23	/** Booted, synced, and drawing: the bar every online entry must clear. */
24	async function waitForOnlineGame(page: Page): Promise<void> {
25	  await page.waitForFunction(() => window.__monecraft !== undefined, undefined, { timeout: 30000 });
26	  await page.waitForFunction(() => window.__monecraft!.net?.status() === "online", undefined, { timeout: 30000 });
27	  await page.waitForFunction(() => window.__monecraft!.renderer.renderedTriangles() > 0, undefined, { timeout: 30000 });
28	}
29	
30	/** Registers a fresh account: welcome gate's "Sign in" → auth screen → sign-up. */
31	async function signUp(page: Page, name: string, email: string): Promise<void> {
32	  await page.getByRole("button", { name: "Sign in", exact: true }).click();
33	  await page.getByRole("button", { name: "I need an account" }).click();
34	  await page.getByLabel("Email").fill(email);
35	  await page.getByLabel("Display name").fill(name);
36	  await page.getByLabel("Password").fill("hunter2hunter2");
37	  await page.getByRole("button", { name: "Create account" }).click();
38	}
39	
40	/** From the account home, creates an online profile and enters its world list. */
41	async function createOnlineProfile(page: Page, name: string): Promise<void> {
42	  // Sign-up → session probe → account home spans two network hops.
43	  await expect(page.getByText("Online Profiles")).toBeVisible({ timeout: 15000 });
44	  await page.getByTestId("new-online-profile").click();
45	  await page.getByLabel("Profile name").fill(name);
