95	  await createOnlineProfile(host, "Hosta");
96	
97	  // Creative, so the host's block breaks are instant on the server side.
98	  await host.getByTestId("new-online-world").click();
99	  await host.getByLabel("World name").fill("Co-op Test");
100	  await host.getByLabel("World seed").fill("4242");
101	  await host.getByRole("button", { name: "Creative mode" }).click();
102	  await host.getByRole("button", { name: "Create World" }).click();
103	  await waitForOnlineGame(host);
104	
105	  // Mint the invite with the host's cookies (the menu's Copy button wraps the
106	  // same endpoint; the clipboard is out of reach in headless runs).
107	  const worldId = await host.evaluate(async () => {
108	    const response = await fetch("/api/worlds");
109	    const { worlds } = (await response.json()) as { worlds: Array<{ id: string }> };
110	    return worlds[0].id;
111	  });
112	  const inviteToken = await host.evaluate(async (id) => {
113	    const response = await fetch(`/api/worlds/${id}/invites`, { method: "POST" });
114	    const { token } = (await response.json()) as { token: string };
115	    return token;
116	  }, worldId);
117	
118	  // ── the friend: invite link → register on the landing page → same world ──
119	  const friendContext = await browser.newContext();
120	  const friend = await friendContext.newPage();
121	  watchErrors(friend, errors);
122	  await friend.goto(`/join/${inviteToken}`);
123	
124	  // The landing page previews the world before any sign-in, then embeds the
125	  // account panel; registering accepts the invite in place.
126	  await expect(friend.getByText("Co-op Test")).toBeVisible({ timeout: 15000 });
127	  await expect(friend.getByText(/sign in to join/)).toBeVisible();
128	  await signUp(friend, "Frienda", `friend-${runTag}@example.com`);
129	  await expect(friend.getByText(/You've joined/)).toBeVisible({ timeout: 15000 });
130	  await friend.getByRole("link", { name: "Open the game" }).click();
131	
132	  // The landing page marked online-used, so the shell finds the fresh session
133	  // and opens the account home. The joined world surfaces under any profile
134	  // (membership is account-level), labelled as joined rather than owned.
135	  await createOnlineProfile(friend, "Friend");
136	  await expect(friend.getByTestId(`online-world-${worldId}`)).toContainText("Joined");
137	  await friend.getByTestId(`online-world-${worldId}`).click();
138	  await waitForOnlineGame(friend);
139	
140	  // ── both replicas agree there are two players in the room ────────────────
